from Bio import SeqIO
from Bio.Seq import reverse_complement
import subprocess

seqs = {}
for record in SeqIO.parse("sequences.fasta", "fasta"):
    seqs[record.id] = str(record.seq)

def calc_tm(seq):
    """Calculate Tm using primer3's oligotm tool"""
    result = subprocess.run(
        ['oligotm', '-tp', '1', '-sc', '1', '-mv', '50', '-dv', '2', '-n', '0.8', '-d', '500', seq],
        capture_output=True,
        text=True
    )
    if result.returncode == 0:
        try:
            return float(result.stdout.strip())
        except:
            return None
    return None

# Test oligotm
test_seqs = [
    "ATGAGCAAGGGCGAGGAGCTGTTCA",
    "ATGAGCAAGGGCGAGGAGCTG",
    "ATGAGCAAGGGCGAGGAG",
    "CGACACGGAAATGTTGAATACTCAT",
    "CGACACGGAAATGTTGAA",
]

for seq in test_seqs:
    tm = calc_tm(seq)
    print(f"Tm for {seq} (len={len(seq)}): {tm}")
PYSCRIPT
